import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.Optional;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;

class OrderServiceTest {

    private OrderRepository orders;
    private OrderService service;

    @BeforeEach
    void setUp() {
        orders = mock(OrderRepository.class);
        service = new OrderService(orders, mock(OrderLineRepository.class),
                mock(OutboxRepository.class), mock(Catalog.class), JsonMapper.builder().build());
    }

    @Test
    void markPaidMarksAnExistingOrderAsPaid() {
        Order order = new Order("customer-1", "EUR", 1200);
        when(orders.findById(42L)).thenReturn(Optional.of(order));

        service.markPaid(new PaymentSettled("42", "pay-1", 1200));

        assertThat(order.getStatus()).isEqualTo(OrderStatus.PAID);
    }

    @Test
    void markPaidThrowsOrderNotFoundForAnUnknownOrder() {
        when(orders.findById(42L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> service.markPaid(new PaymentSettled("42", "pay-1", 1200)))
                .isInstanceOf(OrderNotFoundException.class)
                .hasMessageContaining("42")
                .extracting("orderId").isEqualTo("42");
    }

    @Test
    void markPaidThrowsOrderNotFoundForAnOrderIdThatIsNotANumber() {
        assertThatThrownBy(() -> service.markPaid(new PaymentSettled("not-a-number", "pay-1", 1200)))
                .isInstanceOf(OrderNotFoundException.class)
                .hasMessageContaining("not-a-number");
    }

    @Test
    void orderNotFoundExceptionIsARuntimeExceptionCarryingTheOrderId() {
        OrderNotFoundException e = new OrderNotFoundException("7");

        assertThat(e).isInstanceOf(RuntimeException.class);
        assertThat(e.getOrderId()).isEqualTo("7");
        assertThat(e.getMessage()).contains("7");
    }
