// Runs the real listener, container factory and error handler against an
// embedded broker. OrderService is mocked so no database is needed.
@SpringBootTest(classes = {PaymentSettledListener.class, KafkaErrorHandlingConfig.class},
        properties = "spring.kafka.consumer.auto-offset-reset=earliest")
@ImportAutoConfiguration({KafkaAutoConfiguration.class, JacksonAutoConfiguration.class})
@EmbeddedKafka(partitions = 1, topics = {PaymentSettledListenerTest.TOPIC, PaymentSettledListenerTest.DLT},
        bootstrapServersProperty = "spring.kafka.bootstrap-servers")
class PaymentSettledListenerTest {

    static final String TOPIC = "payment-settled";
    static final String DLT = "payment-settled.DLT";

    private static final Duration DLT_WAIT = Duration.ofSeconds(10);
    private static final AtomicInteger DLT_GROUPS = new AtomicInteger();

    @Autowired
    private KafkaTemplate<String, String> kafka;
    @Autowired
    private EmbeddedKafkaBroker broker;
    @Autowired
    private KafkaListenerEndpointRegistry registry;
    @MockitoBean
    private OrderService orders;

    private Consumer<String, String> dlt;

    @BeforeEach
    void setUp() {
        for (MessageListenerContainer container : registry.getListenerContainers()) {
            ContainerTestUtils.waitForAssignment(container, 1);
        }
        Map<String, Object> props = new HashMap<>();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, broker.getBrokersAsString());
        props.put(ConsumerConfig.GROUP_ID_CONFIG, "dlt-test-" + DLT_GROUPS.incrementAndGet());
        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
        props.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, false);
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        dlt = new KafkaConsumer<>(props);
        broker.consumeFromAnEmbeddedTopic(dlt, DLT);
    }

    @AfterEach
    void tearDown() {
        dlt.close();
    }

    @Test
    void marksTheOrderPaidForAValidRecord() {
        String message = payment("100");

        kafka.send(TOPIC, message);

        verify(orders, timeout(10_000)).markPaid(new PaymentSettled("100", "pay-100", 100));
        assertThat(deadLetters(message, Duration.ofSeconds(2))).isEmpty();
    }

    @Test
    void retriesATransientFailureAndSucceedsWithoutDeadLettering() {
        String message = payment("200");
        AtomicInteger calls = new AtomicInteger();
        doAnswer(invocation -> {
            if (calls.incrementAndGet() < 3) {
                throw new TransientDataAccessResourceException("db hiccup");
            }
            return null;
        }).when(orders).markPaid(forOrder("200"));

        kafka.send(TOPIC, message);

        verify(orders, timeout(10_000).times(3)).markPaid(forOrder("200"));
        assertThat(deadLetters(message, Duration.ofSeconds(2))).isEmpty();
        verify(orders, times(3)).markPaid(any());
    }

    @Test
    void givesUpAfterFourSpacedAttemptsAndDeadLettersThePersistentTransientFailure() {
        String message = payment("300");
        List<Long> attemptsAtNanos = new CopyOnWriteArrayList<>();
        doAnswer(invocation -> {
            attemptsAtNanos.add(System.nanoTime());
            throw new TransientDataAccessResourceException("db down");
        }).when(orders).markPaid(forOrder("300"));

        long sentAtNanos = System.nanoTime();
        kafka.send(TOPIC, message);

        List<ConsumerRecord<String, String>> dead = deadLetters(message, DLT_WAIT);
        long deadLetteredAtNanos = System.nanoTime();

        assertThat(dead).hasSize(1);
        assertThat(dead.get(0).value()).isEqualTo(message);
        assertThat(attemptsAtNanos).hasSize(4);
        for (int i = 1; i < attemptsAtNanos.size(); i++) {
            long gapMillis = (attemptsAtNanos.get(i) - attemptsAtNanos.get(i - 1)) / 1_000_000;
            assertThat(gapMillis).as("gap before attempt %d", i + 1).isGreaterThanOrEqualTo(100);
        }
        assertThat((deadLetteredAtNanos - sentAtNanos) / 1_000_000)
                .as("time from send to dead letter (ms)").isLessThan(5_000);
        verify(orders, times(4)).markPaid(any());

        assertNextRecordIsStillProcessed("301");
    }

    @Test
    void deadLettersInvalidJsonWithoutCallingTheService() {
        String message = "{\"orderId\": ";

        kafka.send(TOPIC, message);

        List<ConsumerRecord<String, String>> dead = deadLetters(message, DLT_WAIT);
        assertThat(dead).hasSize(1);
        assertThat(dead.get(0).value()).isEqualTo(message);
        verify(orders, never()).markPaid(any());

        assertNextRecordIsStillProcessed("401");
    }

    @Test
    void deadLettersAPaymentForAnUnknownOrderWithoutRetrying() {
        String message = payment("500");
        doThrow(new OrderNotFoundException("500")).when(orders).markPaid(forOrder("500"));

        kafka.send(TOPIC, message);

        List<ConsumerRecord<String, String>> dead = deadLetters(message, DLT_WAIT);
        assertThat(dead).hasSize(1);
        assertThat(dead.get(0).value()).isEqualTo(message);
        verify(orders, times(1)).markPaid(any());

        assertNextRecordIsStillProcessed("501");
    }

    private void assertNextRecordIsStillProcessed(String orderId) {
        String message = payment(orderId);

        kafka.send(TOPIC, message);

        verify(orders, timeout(10_000)).markPaid(forOrder(orderId));
        assertThat(deadLetters(message, Duration.ofSeconds(2))).isEmpty();
    }

    private static String payment(String orderId) {
        return "{\"orderId\":\"" + orderId + "\",\"paymentId\":\"pay-" + orderId
                + "\",\"amount\":" + orderId + "}";
    }

    private static PaymentSettled forOrder(String orderId) {
        return argThat(event -> event != null && orderId.equals(event.orderId()));
    }

    // Everything on the DLT whose value is the given message. Polls until at least
    // one such record shows up or the timeout passes, then drains what is left so
    // duplicates would be caught too.
    private List<ConsumerRecord<String, String>> deadLetters(String message, Duration timeout) {
        List<ConsumerRecord<String, String>> matching = new ArrayList<>();
        long deadline = System.nanoTime() + timeout.toNanos();
        while (System.nanoTime() < deadline) {
            for (ConsumerRecord<String, String> record : dlt.poll(Duration.ofMillis(200))) {
                if (message.equals(record.value())) {
                    matching.add(record);
                }
            }
            if (!matching.isEmpty()) {
                break;
            }
        }
        for (ConsumerRecord<String, String> record : KafkaTestUtils.getRecords(dlt, Duration.ofMillis(500))) {
            if (message.equals(record.value())) {
                matching.add(record);
            }
        }
        return matching;
    }
}
